import * as THREE from './node_modules/three/build/three.module.js';

const viewport = document.querySelector('#viewport');
const scene = new THREE.Scene();
scene.background = new THREE.Color('#16151c');
scene.fog = new THREE.FogExp2('#16151c', 0.026);
const camera = new THREE.PerspectiveCamera(49, innerWidth / innerHeight, 0.1, 100);
const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.65));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.24;
viewport.appendChild(renderer.domElement);

const mat = (color, roughness = .82, metalness = 0) => new THREE.MeshStandardMaterial({ color, roughness, metalness });
const stone = mat('#45414a'), stoneLight = mat('#625b61'), darkStone = mat('#27252d'), gold = mat('#c49a58', .42, .62), warm = mat('#ffb95f', .35), floorMats = ['#37323a','#403a40','#39353d','#454047'].map(c => mat(c));
scene.add(new THREE.HemisphereLight('#a5a9c5', '#352922', 1.5));
const moon = new THREE.DirectionalLight('#c2c7ee', 2.25); moon.position.set(-7, 15, 5); moon.castShadow = true; moon.shadow.mapSize.set(1024,1024); moon.shadow.camera.left=-19; moon.shadow.camera.right=19; moon.shadow.camera.top=19; moon.shadow.camera.bottom=-19; moon.shadow.bias=-.0005; scene.add(moon);
const fillLight = new THREE.PointLight('#d99b58', 27, 24, 2); fillLight.position.set(0,5,0); scene.add(fillLight);
const floor = new THREE.Mesh(new THREE.PlaneGeometry(32,32), mat('#302d35')); floor.rotation.x=-Math.PI/2; floor.position.y=-.12; floor.receiveShadow=true; scene.add(floor);
const room = new THREE.Group(); scene.add(room);
function box(parent, x,y,z, sx,sy,sz, material, cast=true) { const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material); m.position.set(x,y,z); m.castShadow=cast; m.receiveShadow=true; parent.add(m); return m; }
// Large flagstone floor, worn seams, and ritual inlay.
for(let x=-7;x<=7;x++) for(let z=-7;z<=7;z++) { const tile=new THREE.Mesh(new THREE.BoxGeometry(1.94,.12,1.94),floorMats[(Math.abs(x*7+z*13)%4)]); tile.position.set(x*2,-.045,z*2); tile.receiveShadow=true; room.add(tile); if((x+z)%4===0){const crack=new THREE.Mesh(new THREE.BoxGeometry(.035,.008,.54),mat('#29272e')); crack.position.set(x*2+.42,.022,z*2-.25); crack.rotation.y=.35;room.add(crack);} }
const ring = new THREE.Mesh(new THREE.TorusGeometry(3.2,.045,5,80),mat('#8d724c',.48,.5)); ring.rotation.x=Math.PI/2; ring.position.y=.045; room.add(ring);
for(let i=0;i<8;i++){const a=i*Math.PI/4;const rune=box(room,Math.cos(a)*3.2,.052,Math.sin(a)*3.2,.12,.02,.4,gold,false);rune.rotation.y=-a;}
// Wall blocks make a sealed, walkable crypt arena.
for(let i=-6;i<=6;i++){for(const side of [-1,1]){box(room,i*2,1.3,side*14,1.96,2.7,.65,(i%3===0?stoneLight:stone));box(room,i*2,2.73,side*14,2.05,.2,.78,darkStone);box(room,side*14,1.3,i*2,.65,2.7,1.96,(i%3===0?stoneLight:stone));}}
// Pillars, capitals and old sarcophagi.
for(const x of [-11,11])for(const z of [-11,11]){box(room,x,1.6,z,1.45,3.2,1.45,darkStone);box(room,x,1.45,z,1.12,2.9,1.12,stoneLight);box(room,x,3.05,z,1.7,.34,1.7,stone);box(room,x,.22,z,1.8,.4,1.8,gold);}
for(const [x,z] of [[-8,-10],[8,-10],[-8,10],[8,10]]){box(room,x,.55,z,2.2,.9,1.05,stoneLight);box(room,x,1.03,z,1.55,.09,.75,darkStone);box(room,x,.12,z,2.45,.2,1.2,darkStone);}
// Brazier pedestals, emissive flame stones and local light.
const flames=[];
