for(const side of [-1,1]){const leg=new THREE.Mesh(new THREE.CapsuleGeometry(.14,.43,3,7),leather);leg.position.set(side*.18,.36,0);leg.castShadow=true;player.add(leg);legs.push(leg);const boot=box(player,side*.18,.1,.07,.29,.2,.43,darkSteel);}
const arm=new THREE.Mesh(new THREE.CapsuleGeometry(.12,.42,3,7),skin);arm.position.set(.4,1.11,0);arm.rotation.z=-.42;arm.castShadow=true;player.add(arm);
