const playerState={x:0,z:7,hp:100,maxHp:100,level:7,xp:320,gold:45,shards:2,attackCd:0,dodge:0,dodgeCd:0,invuln:0,potionCd:0,attackAnim:0,walk:0,dead:false};

function makeEnemy(type,x,z){const g=new THREE.Group();scene.add(g);const isBoss=type==='boss', enemyMat=mat(isBoss?'#4c343d':'#777178'), bone=mat(isBoss?'#b49a7e':'#c6bda8'), red=mat('#9a454d',.5,.15);const scale=isBoss?1.8:1;g.scale.setScalar(scale);const body=new THREE.Mesh(new THREE.CapsuleGeometry(.36,.64,4,8),enemyMat);body.position.y=.95;body.castShadow=true;g.add(body);const skull=new THREE.Mesh(new THREE.SphereGeometry(.28,12,10),bone);skull.position.y=1.72;skull.castShadow=true;g.add(skull);const eyeMat=new THREE.MeshBasicMaterial({color:isBoss?'#ff3e42':'#e25250'});for(const s of [-1,1]){const eye=new THREE.Mesh(new THREE.SphereGeometry(isBoss?.055:.035,8,6),eyeMat);eye.position.set(s*.1,1.75,-.24);g.add(eye);const armBone=new THREE.Mesh(new THREE.CapsuleGeometry(.11,.56,3,6),bone);armBone.position.set(s*.49,1.02,0);armBone.rotation.z=s*.48;armBone.castShadow=true;g.add(armBone);const leg=new THREE.Mesh(new THREE.CapsuleGeometry(.13,.5,3,6),darkStone);leg.position.set(s*.19,.35,0);g.add(leg);}
 const weapon=box(g,isBoss?.62:.52,1.1,-.03,isBoss?.16:.09,isBoss?1.65:1.15,.12,isBoss?red:darkSteel);weapon.rotation.z=-.25;
 const glow=new THREE.PointLight(isBoss?'#ec4545':'#e35e49',isBoss?2:0.65,4);glow.position.y=1.5;g.add(glow);
