const enemies=[];
makeEnemy('skeleton',-5,1);makeEnemy('skeleton',5,-.4);makeEnemy('skeleton',-4,-6);makeEnemy('boss',1,-7);
const keys=new Set(), touchMove=new Set();let started=false,won=false,hasChest=false,attackCount=0,lastTime=0,toastTimer=0,feedTimer=0,soundOn=false,audioCtx=null;
const $=s=>document.querySelector(s), healthFill=$('#health-fill'), healthLabel=$('#health-label');
function log(text,color=''){const feed=$('#combat-feed');const row=document.createElement('div');row.innerHTML=`<i class="feed-gold">${color||'✦'}</i> ${text}`;feed.appendChild(row);while(feed.children.length>4)feed.firstElementChild.remove();feedTimer=7;}
function toast(text){$('#toast-text').textContent=text;$('#toast').classList.add('show');toastTimer=2.4;}
function updateUI(){healthFill.style.width=`${Math.max(0,playerState.hp/playerState.maxHp*100)}%`;healthLabel.textContent=`${Math.ceil(playerState.hp)} / ${playerState.maxHp}`;$('#level').textContent=String(playerState.level).padStart(2,'0');$('#xp-fill').style.width=`${playerState.xp/500*100}%`;$('#xp-label').textContent=`${playerState.xp} / 500 XP`;$('#gold-count').textContent=playerState.gold;$('#shard-count').textContent=playerState.shards;const boss=enemies.find(e=>e.type==='boss');if(boss){$('#boss-fill').style.width=`${Math.max(0,boss.hp/boss.maxHp*100)}%`;$('#boss-hp-text').textContent=`${Math.max(0,Math.ceil(boss.hp))} / ${boss.maxHp}`;}}
function gainXP(n){playerState.xp+=n;if(playerState.xp>=500){playerState.xp-=500;playerState.level++;playerState.maxHp+=12;playerState.hp=Math.min(playerState.maxHp,playerState.hp+playerState.maxHp);$('#level-up-label').textContent=`LEVEL ${String(playerState.level).padStart(2,'0')}`;$('#level-up').classList.add('show');setTimeout(()=>$('#level-up').classList.remove('show'),2100);log(`Level up! You are now level ${playerState.level}.`,'✧');}updateUI();}
function playTone(freq,duration=.08,type='sine',volume=.035){if(!soundOn)return;try{audioCtx ||= new AudioContext();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration);}catch{}}
function damagePlayer(n){if(playerState.invuln>0||playerState.dead)return;playerState.hp=Math.max(0,playerState.hp-n);playerState.invuln=.48;player.material?.color?.set?.('#ff7777');updateUI();playTone(110,.16,'sawtooth',.045);if(playerState.hp<=0){playerState.dead=true;$('#cover-title').innerHTML='FALLEN IN<br /><em>THE CRYPT</em>';$('#cover-copy').textContent='The crypt claims another soul. Your journey is not over.';$('#start-btn').innerHTML='<span>RISE AGAIN</span><b>↻</b>';$('#screen-cover').classList.remove('hidden');started=false;}}
function attack(){if(!started||playerState.dead||playerState.attackCd>0)return;playerState.attackCd=.43;playerState.attackAnim=.28;attackCount++;let target=null,best=3.55;for(const e of enemies){if(!e.alive)continue;const d=Math.hypot(e.x-playerState.x,e.z-playerState.z);if(d<best){best=d;target=e;}}if(!target){playTone(210,.06,'triangle',.022);return;}const dmg=target.type==='boss'?82:72;target.hp-=dmg;target.hitFlash=.15;target.group.traverse(o=>{if(o.isMesh&&o.material?.emissive){o.material.emissive.set('#6b1616');}});target.group.position.x=target.x+(target.x-playerState.x)*.09;target.group.position.z=target.z+(target.z-playerState.z)*.09;playTone(attackCount%3===0?250:340,.1,'sawtooth',.04);if(target.hp<=0){target.alive=false;target.group.visible=false;playerState.gold+=target.type==='boss'?120:12+Math.floor(Math.random()*9);playerState.shards+=target.type==='boss'?4:1;gainXP(target.type==='boss'?800:110);log(target.type==='boss'?'The Hollow King is vanquished!':'Undead slain — loot collected.',target.type==='boss'?'☠':'◈');if(target.type==='boss')victory();else toast('✦  +110 XP     ◈  LOOT COLLECTED');}else if(target.type==='boss'){toast('✦  THE HOLLOW KING — '+Math.ceil(target.hp)+' VITALITY');}updateUI();}
function victory(){won=true;$('#quest-check').textContent='✓';$('#quest-check').style.color='#98c58d';$('#quest-objective').textContent='The crypt is silent';$('#quest-title').textContent='QUEST COMPLETE';$('#quest-desc').innerHTML='The Hollow King is no more.<br />The way out is yours.';$('#boss-bar').style.display='none';$('#cover-title').innerHTML='THE CRYPT<br /><em>IS SILENT</em>';$('#cover-copy').textContent='The Hollow King is vanquished. Your legend grows.';$('#start-btn').innerHTML='<span>PLAY AGAIN</span><b>↻</b>';setTimeout(()=>$('#screen-cover').classList.remove('hidden'),1800);started=false;}
function usePotion(){if(!started||playerState.potionCd>0||playerState.hp>=playerState.maxHp)return;playerState.hp=Math.min(playerState.maxHp,playerState.hp+42);playerState.potionCd=8;updateUI();toast('✦  POTION — 42 VITALITY RESTORED');log('A healing draught restores your strength.','♥');playTone(580,.18,'sine',.04);}
function dodge(){if(!started||playerState.dodgeCd>0||playerState.dead)return;playerState.dodge=.24;playerState.dodgeCd=1.15;playerState.invuln=.48;playTone(440,.08,'triangle',.025);}
function interact(){if(!started||hasChest||Math.hypot(playerState.x+9,playerState.z-1.5)>2.1)return;hasChest=true;chestGlow.intensity=0;chestLid.rotation.x=-1.05;playerState.gold+=75;playerState.shards+=3;gainXP(140);$('#interact-prompt').style.display='none';log('Ancient chest opened: 75 gold and 3 soul shards.','◈');toast('✦  CHEST OPENED   +75 GOLD   +3 SHARDS');playTone(720,.22,'sine',.04);}

function minimap(){const c=$('#minimap'),ctx=c.getContext('2d'),s=c.width;ctx.clearRect(0,0,s,s);ctx.fillStyle='#1b1b22';ctx.fillRect(0,0,s,s);ctx.strokeStyle='#61584e';ctx.lineWidth=1;ctx.strokeRect(12,12,s-24,s-24);ctx.strokeStyle='#403a3c';ctx.lineWidth=1;for(let i=1;i<7;i++){ctx.beginPath();ctx.moveTo(12+i*16.5,12);ctx.lineTo(12+i*16.5,s-12);ctx.moveTo(12,12+i*16.5);ctx.lineTo(s-12,12+i*16.5);ctx.stroke();}const px=x=>(x+14)/28*(s-24)+12,pz=z=>(z+14)/28*(s-24)+12;ctx.fillStyle='#b29563';ctx.fillRect(px(-9)-2,pz(1.5)-2,4,4);for(const e of enemies){if(e.alive){ctx.beginPath();ctx.fillStyle=e.type==='boss'?'#f2675f':'#bd655e';ctx.arc(px(e.x),pz(e.z),e.type==='boss'?4:2.5,0,7);ctx.fill();}}ctx.beginPath();ctx.fillStyle='#80c9d0';ctx.shadowColor='#69d7de';ctx.shadowBlur=8;ctx.arc(px(playerState.x),pz(playerState.z),3.7,0,7);ctx.fill();ctx.shadowBlur=0;}

function update(dt,time){if(!started)return;playerState.attackCd=Math.max(0,playerState.attackCd-dt);playerState.attackAnim=Math.max(0,playerState.attackAnim-dt);playerState.dodgeCd=Math.max(0,playerState.dodgeCd-dt);playerState.dodge=Math.max(0,playerState.dodge-dt);playerState.invuln=Math.max(0,playerState.invuln-dt);playerState.potionCd=Math.max(0,playerState.potionCd-dt);if(playerState.potionCd===0)$('#potion-cooldown').style.display='none';else $('#potion-cooldown').style.display='block';if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('#toast').classList.remove('show');}if(feedTimer>0){feedTimer-=dt;if(feedTimer<=0){const f=$('#combat-feed');if(f.children.length>1)f.firstElementChild.remove();}}
 let dx=(keys.has('d')||touchMove.has('right')?1:0)-(keys.has('a')||touchMove.has('left')?1:0),dz=(keys.has('s')||touchMove.has('down')?1:0)-(keys.has('w')||touchMove.has('up')?1:0);const moving=dx||dz;if(moving){const len=Math.hypot(dx,dz);dx/=len;dz/=len;const speed=playerState.dodge>0?13:4.7;playerState.x=THREE.MathUtils.clamp(playerState.x+dx*speed*dt,-12.1,12.1);playerState.z=THREE.MathUtils.clamp(playerState.z+dz*speed*dt,-12.1,12.1);playerState.walk+=dt*10;player.rotation.y=Math.atan2(dx,dz);}
 player.position.set(playerState.x,playerState.dodge>0?.14+Math.sin(playerState.dodge/.24*Math.PI)*.17:Math.abs(Math.sin(playerState.walk))*.035,playerState.z);for(let i=0;i<legs.length;i++)legs[i].rotation.x=moving?Math.sin(playerState.walk+i*Math.PI)*.55:0;torso.rotation.z=moving?Math.sin(playerState.walk)*.035:0;const swing=playerState.attackAnim>0?Math.sin((.28-playerState.attackAnim)/.28*Math.PI)*1.8:0;sword.rotation.x=-swing;sword.rotation.z=.4+swing*.45;player.visible=playerState.invuln<=0||Math.floor(time*18)%2===0;
 camera.position.set(playerState.x+9.4,11.3,playerState.z+12.6);camera.lookAt(playerState.x,0.5,playerState.z-1.3);
 let nearChest=!hasChest&&Math.hypot(playerState.x+9,playerState.z-1.5)<2.1;$('#interact-prompt').style.display=nearChest?'flex':'none';
 const alive=enemies.filter(e=>e.alive);const boss=alive.find(e=>e.type==='boss');$('#boss-bar').style.display=boss?'block':'none';
 for(const e of alive){const d=Math.hypot(playerState.x-e.x,playerState.z-e.z),bossMult=e.type==='boss'?1.8:1,spd=(e.type==='boss'?1.25:1.55);e.attackCd-=dt;e.phase+=dt*3; e.group.position.y=Math.sin(e.phase)*.025;if(d>1.65*bossMult){if(d>1.5){e.x+=(playerState.x-e.x)/d*spd*dt;e.z+=(playerState.z-e.z)/d*spd*dt;e.group.position.x=e.x;e.group.position.z=e.z;e.group.rotation.y=Math.atan2(playerState.x-e.x,playerState.z-e.z);}}else if(e.attackCd<=0){e.attackCd=e.type==='boss'?1.7:1.4;damagePlayer(e.type==='boss'?15:9);if(e.type==='boss')toast('☠  THE KING STRIKES');}if(e.hitFlash>0)e.hitFlash-=dt;}
 for(const f of flames)f.scale.y=.8+Math.random()*.55;minimap();}
function frame(now){requestAnimationFrame(frame);const dt=Math.min(.04,(now-lastTime)/1000||0);lastTime=now;update(dt,now/1000);renderer.render(scene,camera);}
requestAnimationFrame(frame);updateUI();

let spellCd=0, shieldCd=0, shieldTime=0;
function useSpell(){if(!started||spellCd>0)return;spellCd=4.5;let target=null,best=9;for(const e of enemies){if(!e.alive)continue;const d=Math.hypot(e.x-playerState.x,e.z-playerState.z);if(d<best){best=d;target=e;}}if(!target){toast('✧  NO TARGET IN RANGE');playTone(180,.1,'triangle');return;}target.hp-=145;target.hitFlash=.2;playTone(610,.18,'sine',.045);log(`Frost lance hits for 145 damage.`,'✧');toast('✧  FROST LANCE — 145 DAMAGE');if(target.hp<=0){target.alive=false;target.group.visible=false;playerState.gold+=target.type==='boss'?120:14;playerState.shards+=target.type==='boss'?4:1;gainXP(target.type==='boss'?800:110);log(target.type==='boss'?'The Hollow King is vanquished!':'Undead slain — loot collected.',target.type==='boss'?'☠':'◈');if(target.type==='boss')victory();}updateUI();}
function cleave(){if(!started||shieldCd>0)return;shieldCd=3.5;playerState.invuln=.25;let hits=0;for(const e of enemies){if(!e.alive||Math.hypot(e.x-playerState.x,e.z-playerState.z)>3.8)continue;hits++;e.hp-=95;e.hitFlash=.16;if(e.hp<=0){e.alive=false;e.group.visible=false;playerState.gold+=e.type==='boss'?120:15;playerState.shards+=e.type==='boss'?4:1;gainXP(e.type==='boss'?800:110);if(e.type==='boss')victory();}}if(hits){log(`Whirling strike hits ${hits} ${hits===1?'foe':'foes'}.`,'⚔');playTone(180,.17,'sawtooth',.045);}else toast('⚔  WHIRLING STRIKE');updateUI();}
function resetGame(){playerState.x=0;playerState.z=7;playerState.hp=playerState.maxHp;playerState.dead=false;playerState.attackCd=0;playerState.gold=45;playerState.shards=2;playerState.xp=320;playerState.level=7;playerState.dodgeCd=0;playerState.potionCd=0;spellCd=0;shieldCd=0;hasChest=false;won=false;chestLid.rotation.x=0;chestGlow.intensity=0;for(const e of enemies){e.hp=e.maxHp;e.alive=true;e.group.visible=true;e.group.position.set(e.x,0,e.z);if(e.type==='boss'){e.x=1;e.z=-7;e.group.position.set(e.x,0,e.z);}else{const starts=e===enemies[0]?[-5,1]:e===enemies[1]?[5,-.4]:[-4,-6];e.x=starts[0];e.z=starts[1];e.group.position.set(e.x,0,e.z);}e.attackCd=1.3;}$('#quest-title').textContent='THE HOLLOW KING';$('#quest-desc').innerHTML='Silence the ancient king<br />and escape the crypt.';$('#quest-check').textContent='◌';$('#quest-check').style.color='';$('#quest-objective').textContent='Defeat the Hollow King';$('#boss-bar').style.display='none';$('#combat-feed').innerHTML='<div><i class="feed-gold">✦</i> The dead stir in the darkness...</div>';started=true;updateUI();}
$('#start-btn').addEventListener('click',()=>{if(playerState.dead||won)resetGame();else started=true;$('#screen-cover').classList.add('hidden');toast('✦  THE DEAD STIR IN THE DARKNESS');});
$('#help-btn').addEventListener('click',()=>$('#help-modal').classList.add('open'));
$('#close-help').addEventListener('click',()=>$('#help-modal').classList.remove('open'));
$('#close-help-2').addEventListener('click',()=>$('#help-modal').classList.remove('open'));
$('#sound-btn').addEventListener('click',()=>{soundOn=!soundOn;$('#sound-btn').style.color=soundOn?'#f4d18a':'';if(soundOn)playTone(440,.08);});
$('#map-toggle').addEventListener('click',()=>{$('.minimap-frame').classList.toggle('map-hidden');});
document.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(e.repeat)return;if(['w','a','s','d'].includes(k))keys.add(k);if(k==='arrowup')keys.add('w');if(k==='arrowdown')keys.add('s');if(k==='arrowleft')keys.add('a');if(k==='arrowright')keys.add('d');if(k===' '||k==='shift')dodge();if(k==='j'||k==='f')attack();if(k==='e')interact();if(k==='1'||k==='q')usePotion();if(k==='2')cleave();if(k==='3')useSpell();if(k==='4')dodge();if(k==='escape')$('#help-modal').classList.toggle('open');});
document.addEventListener('keyup',e=>{const k=e.key.toLowerCase();keys.delete(k);if(k==='arrowup')keys.delete('w');if(k==='arrowdown')keys.delete('s');if(k==='arrowleft')keys.delete('a');if(k==='arrowright')keys.delete('d');});
renderer.domElement.addEventListener('pointerdown',e=>{if(e.button===0)attack();});
document.querySelectorAll('.slot').forEach(slot=>slot.addEventListener('click',()=>{const n=slot.dataset.slot;if(n==='1')usePotion();if(n==='2')cleave();if(n==='3')useSpell();if(n==='4')dodge();document.querySelectorAll('.slot').forEach(s=>s.classList.toggle('active',s===slot));}));
document.querySelectorAll('[data-move]').forEach(button=>{const move=button.dataset.move;button.addEventListener('pointerdown',e=>{e.preventDefault();touchMove.add(move);button.setPointerCapture(e.pointerId);});const stop=e=>{e.preventDefault();touchMove.delete(move);};button.addEventListener('pointerup',stop);button.addEventListener('pointercancel',stop);button.addEventListener('lostpointercapture',()=>touchMove.delete(move));});
$('#touch-attack').addEventListener('pointerdown',e=>{e.preventDefault();attack();});$('#touch-heal').addEventListener('pointerdown',e=>{e.preventDefault();usePotion();});
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.65));});

